import { Config, Context, Effect, Layer, Option } from "effect"
import { Cause } from "effect"
import { promises as fs } from "node:fs"
import * as Path from "node:path"

// ── Trace Entry ────────────────────────────────────────────

interface TraceEntry {
  timestamp: string
  bootId: string
  phase: string
  status: "started" | "completed" | "cached" | "failed"
  message?: string
  cause?: string
  defect?: string
  safeDetails?: Record<string, unknown>
}

// ── Interface ──────────────────────────────────────────────

export interface Interface {
  readonly writePhase: (params: {
    directory: string
    bootId: string
    phase: string
    status: "started" | "completed" | "cached"
    message?: string
    details?: Record<string, unknown>
  }) => Effect.Effect<void>

  readonly writeFailure: (params: {
    directory: string
    bootId: string
    phase: string
    cause: Cause.Cause<unknown>
  }) => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()(
  "@opencode/InstanceTrace",
) {}

// ── BootId Tag ─────────────────────────────────────────────
// Threaded through Context so bootstrap.run shares the same
// bootId that instance-store's boot() generates.

export const BootId = Context.GenericTag<string>(
  "@opencode/InstanceTrace/BootId",
)

// ── Helpers ────────────────────────────────────────────────

function tracePath(dir: string): string {
  return Path.join(dir, ".opencode", "instance-trace.jsonl")
}

const now = () => new Date().toISOString()

// ── Layer ──────────────────────────────────────────────────

export const layer: Layer.Layer<Service> = Layer.effect(
  Service,
  Effect.gen(function* () {
    // Condition 6: kill switch
    const disabled = yield* Config.boolean(
      "OPENCODE_DISABLE_INSTANCE_TRACE",
    ).pipe(Config.withDefault(false))

    if (disabled) {
      return Service.of({
        writePhase: () => Effect.void,
        writeFailure: () => Effect.void,
      })
    }

    // ── Core append helper ──────────────────────────────
    // Condition 7: Effect.promise + fs.promises.appendFile
    // Condition 8: catchAll wraps every write so trace
    //              failures never pollute caller error channels.

    const appendEntry = (
      dir: string,
      entry: TraceEntry,
    ): Effect.Effect<void> =>
      Effect.promise(async () => {
        await fs.mkdir(Path.join(dir, ".opencode"), {
          recursive: true,
        })
        await fs.appendFile(
          tracePath(dir),
          JSON.stringify(entry) + "\n",
        )
      }).pipe(Effect.catchAll(() => Effect.void))

    // ── writePhase ──────────────────────────────────────

    const writePhase = (params: {
      directory: string
      bootId: string
      phase: string
      status: "started" | "completed" | "cached"
      message?: string
      details?: Record<string, unknown>
    }): Effect.Effect<void> =>
      appendEntry(params.directory, {
        timestamp: now(),
        bootId: params.bootId,
        phase: params.phase,
        status: params.status,
        ...(params.message ? { message: params.message } : {}),
        ...(params.details
          ? { safeDetails: params.details }
          : {}),
      })

    // ── writeFailure ────────────────────────────────────
    // Condition 3: full cause serialization — Cause.pretty(),
    //              error message, and defect for Cause.die.

    const writeFailure = (params: {
      directory: string
      bootId: string
      phase: string
      cause: Cause.Cause<unknown>
    }): Effect.Effect<void> => {
      const pretty = Cause.pretty(params.cause)
      const causeError = Cause.failureOrCause(params.cause)
      const message =
        causeError._tag === "Left"
          ? causeError.left instanceof Error
            ? causeError.left.message
            : String(causeError.left)
          : pretty.slice(0, 200)
      const defect = Cause.isDie(params.cause)
        ? String(params.cause.defect)
        : undefined

      return appendEntry(params.directory, {
        timestamp: now(),
        bootId: params.bootId,
        phase: `${params.phase}.failed`,
        status: "failed",
        message,
        cause: pretty,
        ...(defect ? { defect } : {}),
      })
    }

    return Service.of({ writePhase, writeFailure })
  }),
)

