      Effect.map(({ InstanceTrace }) => InstanceTrace.layer),
      Effect.catchAll(() =>
        Effect.succeed(Layer.succeedContext(Context.empty())),
      ),
    )
    return InstanceStore.defaultLayer.pipe(
      Layer.provide(InstanceBootstrap.defaultLayer),
      Layer.provide(traceLayer),
    )
  }),
)

